value.value:
@if(
    not(empty(trim(pipeline().parameters.p_incr_from_val))),
    trim(pipeline().parameters.p_incr_from_val),
    formatDateTime(
        addDays(
            convertTimeZone(utcnow(), 'UTC', 'Korea Standard Time'),
            sub(
                0,
                int(
                    if(
                        empty(trim(pipeline().parameters.p_incr_days)),
                        variables('pv_condition_interval'),
                        trim(pipeline().parameters.p_incr_days)
                    )
                )
            )
        ),
        'yyyy-MM-dd'
    )
)
